"""
Pydantic request/response schemas for the OtoScope AI API.
"""
from __future__ import annotations

from typing import Optional

from pydantic import BaseModel

_DISCLAIMER = (
    "RESEARCH ONLY. This output is generated by an unvalidated research model. "
    "It has not been clinically validated and must not be used for diagnosis, "
    "treatment decisions, or patient care."
)


class PredictionResponse(BaseModel):
    predicted_class: str
    predicted_index: int
    confidence: float
    class_probs: dict[str, float]
    uncertainty: Optional[float] = None
    # Safety flags
    low_confidence: bool = False   # True when max(softmax) < 0.5
    uncertain: bool = False        # True when MC Dropout std > 0.15
    research_disclaimer: str = _DISCLAIMER


class ExplainResponse(BaseModel):
    predicted_class: str
    predicted_index: int
    confidence: float
    class_probs: dict[str, float]
    uncertainty: Optional[float] = None
    # Safety flags
    low_confidence: bool = False
    uncertain: bool = False
    research_disclaimer: str = _DISCLAIMER
    # Base64-encoded PNG images
    heatmap_gradcam: str
    heatmap_gradcam_pp: str
    heatmap_int_grads: str
    heatmap_guided_bp: str
    chart_comparison: str
    chart_tda: str
    chart_confidence: str
    # Structured data
    tda_importance: dict[str, float]
    tda_values: dict[str, float]
    clinical_reasoning: dict
